---
// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
// Web search: The agent's searches as a trail: what it asked, what came back, what it read or skipped, and the answer with its sources.
// The markup, CSS and script are designme.dev's own, run by the shared core in ../core, which mounts the component when it scrolls
// into view and plays its demo. To show your own data, change web-search.js. The markup is kept exactly as it is (is:raw).
import type { HTMLAttributes } from 'astro/types';
import '../core/designme.css';
import './web-search.css';

export interface Props extends HTMLAttributes<'div'> {
  /** "soft" or "clean" draws it in that style. Leave it out for Blueprint, or for the style set on <html> (data-style="soft" or "clean") */
  'data-style'?: 'soft' | 'clean';
}
const { class: className, ...rest } = Astro.props;
---
<div class:list={['card', 'bare', className]} data-c="web-search" {...rest}>
  <div class="stage-in"><Fragment is:raw>
<div class="wsx panel">
  <button class="wsx-h" aria-expanded="true"><span class="wsx-ic"><span class="spin"></span></span><span class="wsx-st shim">Searching the web</span><span class="wsx-marks" aria-hidden="true"></span><svg class="i xs"><use href="#i-chev-d"/></svg></button>
  <div class="fold wsx-fold"><div><div class="wsx-list"></div></div></div>
  <div class="wsx-ans"></div>
  <p class="wsx-sr" role="status"></p>
</div>
  </Fragment></div>
</div>
<script>
  import './web-search.js';
</script>

/* Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync. */
/* ---------- Web search ---------- */
/* the agent's searches as a trail: each query with what came back, each page with whether it was read, skimmed or skipped and
   why; once done it folds to one line, and the answer under it points back at its pages */
/* hover fills are a quiet 5%, so they show wherever the trail sits (on the stage, --dm-row is the stage's own colour) */
.wsx{padding:6px;display:flex;flex-direction:column;font-size:13px;--dm-row:color-mix(in srgb,var(--dm-fg) 5%,transparent)}
/* the head's mark sits as far from the top as from the side: 16px in from the panel's edges (owner, 21 Nov: "more padding at
   the top of the card?") */
.wsx-h{display:flex;align-items:center;gap:10px;width:100%;padding:10px;border-radius:var(--dm-r-in);text-align:left;font-size:13.5px;transition:background var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.wsx-h:hover{background:var(--dm-row)}}
/* every part on shared columns, in every style (owner, 18 Nov): the head's mark and every row's mark (the search glass, the
   asked-again arrow, a page's site initial) are centred in one 20px column, and every row's words start where the head's do */
.wsx-ic{width:20px;height:20px;flex:none;display:grid;place-items:center;color:var(--dm-fg2)}
.wsx-ic .spin{width:11px;height:11px}
.wsx-st{flex:1;min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wsx-h>.i{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.wsx-h[aria-expanded="false"]>.i{transform:rotate(-90deg)}
/* the sites it went to, as a small stack of initials, the rest counted */
/* side by side, never stacked over each other (owner, 18 Nov) */
.wsx-marks{display:flex;align-items:center;gap:2px}
.wsx-marks span{width:20px;height:20px;border-radius:50%;display:grid;place-items:center;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500;transition:background .2s,color .2s}
.wsx-marks span.n{background:var(--dm-surface);color:var(--dm-muted);box-shadow:inset 0 0 0 1px color-mix(in srgb,var(--dm-line) 50%,transparent);font-size:10px}
.wsx-marks span.hl{background:var(--dm-fg2);color:var(--dm-surface)}
.wsx-list{display:flex;flex-direction:column;gap:2px;padding:2px 0 var(--dm-s-1)}
.wsx-q{display:flex;flex-direction:column}
.wsx-qh{display:grid;grid-template-columns:20px minmax(0,1fr) auto auto 12px;align-items:center;column-gap:10px;width:100%;padding:6px 10px;border-radius:calc(10px * var(--dm-rk-m,var(--dm-rk)));text-align:left;transition:background var(--dm-t-fast)}
.wsx-q.hl>.wsx-qh{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.wsx-qh:hover{background:var(--dm-row)}}
.wsx-qh>.i:first-child{justify-self:center;color:var(--dm-muted)}
.wsx-qh .t{min-width:0;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wsx-qh .n,.wsx-qh .tm{font-size:12px;color:var(--dm-muted);white-space:nowrap}
/* a query and its Searching have the loader's sweep (.shim) while it runs: their own colours step aside for it */
.wsx-qh .t:not(.shim){color:var(--dm-fg)}
.wsx-qh .n.shim{color:transparent}
@media (prefers-reduced-motion:reduce){.wsx-qh .n.shim{color:var(--dm-fg)}}
.wsx-qh .n{margin-right:-2px}
.wsx-qh .n.none{color:var(--dm-warn)}
.wsx-qh>.i:last-child{color:var(--dm-muted);transition:transform .32s var(--dm-ease)}
.wsx-qh[aria-expanded="true"]>.i:last-child{transform:rotate(90deg)}
/* a search that found nothing has no chevron and keeps no room for one: its count and time end where the chevrons and the
   pages' tags end (owner, 21 Nov) */
.wsx-qh.empty{grid-template-columns:20px minmax(0,1fr) auto auto}
.wsx-qh.empty>.i:last-child{display:none}
/* the asked-again note is a row of the trail like the queries: as tall as a query row, so the lines keep one rhythm (owner, 23 Nov) */
.wsx-rw{display:flex;align-items:center;gap:10px;min-height:32px;margin-top:2px;padding:0 10px;font-size:12px;color:var(--dm-muted)}
.wsx-rw .i{margin-inline:4px}
.wsx-rs{list-style:none;margin:0;padding:2px 0 var(--dm-s-1);display:flex;flex-direction:column;gap:2px}
.wsx-r{display:grid;grid-template-columns:20px minmax(0,1fr) auto;column-gap:10px;align-items:center;padding:5px 10px;border-radius:calc(9px * var(--dm-rk-m,var(--dm-rk)));transition:background var(--dm-t-fast);cursor:default}
.wsx-r.hl{background:var(--dm-row)}
@media (hover:hover) and (pointer:fine){.wsx-r:hover{background:var(--dm-row)}}
.wsx-r:focus-visible{outline-offset:-2px}
.wsx-fav{width:20px;height:20px;border-radius:calc(6px * var(--dm-rk-s,var(--dm-rk)));display:grid;place-items:center;background:var(--dm-chip);color:var(--dm-fg2);font-size:10.5px;font-weight:500}
.wsx-r .tx{display:flex;flex-direction:column;min-width:0;line-height:1.35}
.wsx-r .t{white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12.5px;color:var(--dm-fg)}
.wsx-r .d{font-size:11.5px;color:var(--dm-muted);white-space:nowrap;overflow:hidden;text-overflow:ellipsis}
.wsx-r.skip .t{color:var(--dm-muted)}
.wsx-r .tag .spin{width:9px;height:9px}
/* on a hovered or lit row the grey Read and Skimmed chips lift to white (one step lighter in dark mode), so they stand out
   against the row's hover fill rather than melting into it (owner, 22 Nov), in every style */
.wsx{--dm-wsx-lift:var(--dm-surface)}
:root[data-theme="dark"] .wsx{--dm-wsx-lift:var(--dm-hover)}
@media (prefers-color-scheme:dark){:root:not([data-theme="light"]) .wsx{--dm-wsx-lift:var(--dm-hover)}}
.wsx-r .tag{transition:background-color var(--dm-t-fast)}
@media (hover:hover) and (pointer:fine){.wsx-r:is(:hover,.hl) .tag:not(.warn){background:var(--dm-wsx-lift)}}
.wsx-ans{padding:var(--dm-s-2) 10px 6px;font-size:13.5px;line-height:1.6;color:var(--dm-fg)}
.wsx-ans:empty{display:none}
/* the number sits in the middle of its circle: its line is as tall as its figures, so a taller line round it (Clean's 22px
   answer lines set it 2.5px low) never moves it (owner, 21 Nov: "padding is off in this number") */
/* a citation number is a true circle, 18 by 18 (owner, 23 Nov: it looked like neither a circle nor a square) */
.wsx-cite{display:inline-grid;place-items:center;min-width:18px;height:18px;padding:0 4px;margin:0 1px;border-radius:50%;background:var(--dm-chip);color:var(--dm-fg2);font-size:11px;line-height:1;font-weight:500;vertical-align:1px;transition:background var(--dm-t-fast),color var(--dm-t-fast)}
.wsx-cite.on{background:var(--dm-fg2);color:var(--dm-surface)}
@media (hover:hover) and (pointer:fine){.wsx-cite:hover{background:var(--dm-fg2);color:var(--dm-surface)}}
.wsx-sr{position:absolute;width:1px;height:1px;margin:-1px;padding:0;overflow:hidden;clip-path:inset(50%);white-space:nowrap}
/* Clean (lead and owner, 18 Nov): a card of its own, bare or not, as Reasoning trail is: a hairline-outlined round card
   with the search head on top and a hairline under it, everything on shared columns. Content sits 16px in from the card's
   edges. The head's spinner (a globe once done) sits in a 28px neutral tile, and every row's leading mark (a query's search
   glass, the asked-again arrow, a page's site initial) is centred in that same 28px column, so every row's words start where
   the head's do. A row's hover fill spans the content, from the tile's left edge to the content's right edge, never wider;
   the chevrons are centred in a 28px column at the end, the one the head's chevron circle (its quiet hover) fills. A row
   with no chevron (a page, a search that found nothing) keeps no room for one: its tag or time ends on the content's right
   edge (owner, 22 Nov). The answer is the card's own paragraph under a hairline. The card grows and
   shrinks with what it holds (grow()), so as the trail folds once the searching is done it eases down to the head and the
   answer, staying centred. Colour only for meaning: "No results" and a skipped page in the warning colour; sites, counts
   and pages read are grey */
:root[data-style="clean"] .wsx.wsx.wsx,:root [data-style="clean"] .wsx.wsx.wsx,:root [data-style="clean"].wsx.wsx.wsx{padding:0;background:var(--dm-surface);box-shadow:var(--dm-shadow);border-radius:var(--dm-r-card);overflow:clip;container-type:inline-size}
/* on a phone the head drops its stack of site initials, so its words fit: "3 searches, 6 pages read" whole */
@container (max-width:400px){:root[data-style="clean"] .wsx-marks,:root [data-style="clean"] .wsx-marks,:root [data-style="clean"].wsx-marks{display:none}}
:root[data-style="clean"] .wsx.growing,:root [data-style="clean"] .wsx.growing,:root [data-style="clean"].wsx.growing{overflow-clip-margin:0px}
/* the head's tile sits 16px from the top as from the side, and its chevron's circle 16px from the top and the right */
:root[data-style="clean"] .wsx-h,:root [data-style="clean"] .wsx-h,:root [data-style="clean"].wsx-h{min-height:calc(28px + 2 * var(--dm-strip-y));padding:0 23px 0 16px;gap:12px;border-radius:0;font-size:13.5px}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .wsx-h:hover,:root [data-style="clean"] .wsx-h:hover,:root [data-style="clean"].wsx-h:hover{background:none}}
:root[data-style="clean"] .wsx-h:focus-visible,:root [data-style="clean"] .wsx-h:focus-visible,:root [data-style="clean"].wsx-h:focus-visible{outline-offset:-2px;border-radius:var(--dm-r-card)}
:root[data-style="clean"] .wsx-ic,:root [data-style="clean"] .wsx-ic,:root [data-style="clean"].wsx-ic{width:28px;height:28px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));background:var(--dm-chip);box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .wsx-st,:root [data-style="clean"] .wsx-st,:root [data-style="clean"].wsx-st{font-weight:500}
:root[data-style="clean"] .wsx-st:not(.shim),:root [data-style="clean"] .wsx-st:not(.shim),:root [data-style="clean"].wsx-st:not(.shim){color:var(--dm-fg)}
:root[data-style="clean"] .wsx-marks,:root [data-style="clean"] .wsx-marks,:root [data-style="clean"].wsx-marks{margin-right:2px}
:root[data-style="clean"] .wsx-h>.i,:root [data-style="clean"] .wsx-h>.i,:root [data-style="clean"].wsx-h>.i{width:14px;height:14px;border-radius:50%;box-shadow:0 0 0 7px transparent;transition:transform var(--dm-t) var(--dm-ease),background-color var(--dm-t-fast) var(--dm-ease),box-shadow var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}
@media (hover:hover) and (pointer:fine){:root[data-style="clean"] .wsx-h:hover>.i,:root [data-style="clean"] .wsx-h:hover>.i,:root [data-style="clean"].wsx-h:hover>.i{background:var(--dm-row);box-shadow:0 0 0 7px var(--dm-row);color:var(--dm-fg)}}
/* the first row's words sit 16px under the divider, its hover box reaching out 6px round them (owner, 19 Nov: a body's
   first row sits 16px under a divider, no more), and the list ends as far under its last row */
:root[data-style="clean"] .wsx-list,:root [data-style="clean"] .wsx-list,:root [data-style="clean"].wsx-list{gap:0;padding:10px 16px;border-top:1px solid var(--dm-line)}
:root[data-style="clean"] .wsx-qh,:root [data-style="clean"] .wsx-qh,:root [data-style="clean"].wsx-qh{grid-template-columns:28px minmax(0,1fr) auto auto 28px;column-gap:12px;width:calc(100% + 16px);margin-inline:-8px;padding:6px 8px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .wsx-qh>.i,:root [data-style="clean"] .wsx-qh>.i,:root [data-style="clean"].wsx-qh>.i{justify-self:center}
:root[data-style="clean"] .wsx-qh .n,:root [data-style="clean"] .wsx-qh .n,:root [data-style="clean"].wsx-qh .n{margin-right:-4px}
:root[data-style="clean"] .wsx-qh.empty,:root [data-style="clean"] .wsx-qh.empty,:root [data-style="clean"].wsx-qh.empty{grid-template-columns:28px minmax(0,1fr) auto auto}
:root[data-style="clean"] .wsx-qh .n,:root [data-style="clean"] .wsx-qh .n,:root [data-style="clean"].wsx-qh .n,:root[data-style="clean"] .wsx-qh .tm,:root [data-style="clean"] .wsx-qh .tm,:root [data-style="clean"].wsx-qh .tm{font-variant-numeric:tabular-nums}
:root[data-style="clean"] .wsx-rw,:root [data-style="clean"] .wsx-rw,:root [data-style="clean"].wsx-rw{margin-top:0;padding:0;gap:12px}
:root[data-style="clean"] .wsx-rw .i,:root [data-style="clean"] .wsx-rw .i,:root [data-style="clean"].wsx-rw .i{margin-inline:8px}
:root[data-style="clean"] .wsx-rs,:root [data-style="clean"] .wsx-rs,:root [data-style="clean"].wsx-rs{padding:0 0 4px;gap:0}
/* a row's hover fill reaches 8px out round its content, so nothing in it (the Read chip, the mark) touches the fill's edge (owner, 23 Nov) */
:root[data-style="clean"] .wsx-r,:root [data-style="clean"] .wsx-r,:root [data-style="clean"].wsx-r{grid-template-columns:28px minmax(0,1fr) auto;column-gap:12px;margin-inline:-8px;padding:6px 8px;border-radius:calc(7px * var(--dm-rk-m,var(--dm-rk)));transition:background-color var(--dm-t-fast) var(--dm-ease)}
:root[data-style="clean"] .wsx-fav,:root [data-style="clean"] .wsx-fav,:root [data-style="clean"].wsx-fav{justify-self:center;border-radius:calc(4px * var(--dm-rk-s,var(--dm-rk)));box-shadow:inset 0 0 0 1px var(--dm-hair)}
:root[data-style="clean"] .wsx-ans,:root [data-style="clean"] .wsx-ans,:root [data-style="clean"].wsx-ans{padding:16px;border-top:1px solid var(--dm-line);line-height:22px}
/* Clean dark's hover fill is lighter than its --dm-hover, so a lifted chip steps further up to stand out on it */
:root[data-style="clean"][data-theme="dark"] .wsx,:root[data-theme="dark"] [data-style="clean"] .wsx,:root[data-theme="dark"] [data-style="clean"].wsx{--dm-wsx-lift:color-mix(in srgb,var(--dm-fg) 16%,var(--dm-surface))}
@media (prefers-color-scheme:dark){:root[data-style="clean"]:not([data-theme="light"]) .wsx,:root:not([data-theme="light"]) [data-style="clean"] .wsx,:root:not([data-theme="light"]) [data-style="clean"].wsx{--dm-wsx-lift:color-mix(in srgb,var(--dm-fg) 16%,var(--dm-surface))}}
:root[data-style="clean"] .wsx-cite,:root [data-style="clean"] .wsx-cite,:root [data-style="clean"].wsx-cite{transition:background-color var(--dm-t-fast) var(--dm-ease),color var(--dm-t-fast) var(--dm-ease)}

// Generated from designme.dev by scripts/sync.mjs. Edit the site, then sync.
import { $, $$, DM, I, enter, grow, html, swap } from '../core/core.js';
DM.def('web-search', (r, c) => {
  r.innerHTML = r.innerHTML.replace('{chev}', I('chev-d','xs'));
  // the searches: what was asked, how many results, how long it took, and the pages it opened. The first finds nothing and is
  // asked again in other words
  const Q = [
    { q:'stripe usage based billing limits 2026 enterprise tier', n:0, ms:'0.6s' },
    { q:'stripe usage-based billing limits', n:5, ms:'0.9s', from:0, p:[
      ['Usage-based billing', 'stripe.com', 'Oct 2026', 'read'], ['Meters and billing thresholds', 'stripe.com', 'Sep 2026', 'read', 1],
      ['How we moved 40k customers to usage billing', 'medium.com', 'Mar 2026', 'skim'], ['Why SaaS pricing is moving to usage', 'ft.com', 'Aug 2026', 'paywall'] ] },
    { q:'metronome vs orb usage billing', n:6, ms:'1.1s', p:[
      ['Metronome vs Orb: a fair comparison', 'metronome.com', 'Jul 2026', 'read', 2], ['Orb pricing and plans', 'withorb.com', 'Oct 2026', 'read'],
      ['orb-billing/examples: sending usage events', 'github.com', 'Jun 2026', 'read'], ['Anyone switched from Stripe Billing to Orb?', 'reddit.com', 'May 2026', 'blocked'] ] }
  ];
  const ST = { read:['Read', ''], skim:['Skimmed', ''], paywall:['Skipped: paywall', 'warn'], blocked:['Skipped: blocked', 'warn'], timeout:['Skipped: timeout', 'warn'] };
  const root = $('.wsx', r), head = $('.wsx-h', r), ic = $('.wsx-ic', r), st = $('.wsx-st', r), marks = $('.wsx-marks', r), fold = $('.wsx-fold', r), list = $('.wsx-list', r), ans = $('.wsx-ans', r), sr = $('.wsx-sr', r);
  const say = t => { sr.textContent = t; };
  // the card grows and shrinks with what it holds (grow()), eased and centred, in every style (owner, 18 Nov), instead of
  // keeping the height it had once the trail folds
  c.offs.push(grow(root));
  const setOpen = o => { head.setAttribute('aria-expanded', o); fold.classList.toggle('shut', !o); };
  head.onclick = () => setOpen(head.getAttribute('aria-expanded') !== 'true');
  const sites = [];
  const drawMarks = () => { const u = [...new Set(sites)]; marks.innerHTML = u.slice(0, 4).map(s => `<span data-s="${s}">${s[0].toUpperCase()}</span>`).join('') + (u.length > 4 ? `<span class="n">+${u.length - 4}</span>` : ''); };
  const qOpen = (el, o) => { const b = $('.wsx-qh', el), f = $('.fold', el); if (!f) return; b.setAttribute('aria-expanded', o); f.classList.toggle('shut', !o); };
  const pages = {};
  let done = false;
  c.run(async () => {
    await c.wait(500);
    for (const [k, q] of Q.entries()){
      const el = html(`<div class="wsx-q" data-k="${k}"><button class="wsx-qh${q.n ? '' : ' empty'}" aria-expanded="false">${I('search','xs')}<span class="t shim">${q.q}</span><span class="n shim">Searching</span><span class="tm num"></span>${I('chev-r','xs')}</button>${q.from != null ? `<span class="wsx-rw">${I('refresh','xs')}Asked again in other words</span>` : ''}${q.p ? '<div class="fold shut"><div><ul class="wsx-rs"></ul></div></div>' : ''}</div>`);
      // the head says what is happening; the query and its pages are in the rows under it, so it repeats neither (owner, 18 Nov)
      list.appendChild(el); enter(el); swap(st, 'Searching the web');
      const b = $('.wsx-qh', el); b.onclick = () => { if ($('.fold', el)) qOpen(el, b.getAttribute('aria-expanded') !== 'true'); };
      await c.wait(1100);
      $('.t', b).classList.remove('shim'); $('.tm', b).textContent = q.ms;
      const n = $('.n', b); n.classList.remove('shim'); n.textContent = q.n ? `${q.n} results` : 'No results'; n.classList.toggle('none', !q.n);
      b.setAttribute('aria-label', `${q.q}: ${q.n ? q.n + ' results' : 'no results'}, ${q.ms}`);
      say(q.n ? `${q.n} results for ${q.q}` : `No results for ${q.q}. Asking again in other words`);
      if (!q.p){ await c.wait(500); continue; }
      qOpen(el, true); const ul = $('.wsx-rs', el);
      swap(st, 'Reading the pages');
      for (const [t, d, when, s, cite] of q.p){
        const li = html(`<li class="wsx-r" tabindex="0" data-tip="${t} · ${d}"><span class="wsx-fav" aria-hidden="true">${d[0].toUpperCase()}</span><span class="tx"><span class="t">${t}</span><span class="d">${d} · ${when}</span></span><span class="tag"><span class="spin"></span><span class="shim">Reading</span></span></li>`);
        ul.appendChild(li); enter(li); sites.push(d); drawMarks(); if (cite) pages[cite] = { li, q:el, d };
        await c.wait(420);
        const g = $('.tag', li); g.className = 'tag ' + ST[s][1]; g.textContent = ST[s][0]; li.classList.toggle('skip', s !== 'read' && s !== 'skim');
        li.setAttribute('aria-label', `${t}, ${d}, ${when}: ${ST[s][0]}`);
      }
      await c.wait(500); qOpen(el, false);
    }
    // done: the trail folds to one line, and the answer streams in under it, citing its pages
    done = true; ic.innerHTML = I('globe','xs'); st.classList.remove('shim');
    const read = Q.flatMap(q => q.p || []).filter(p => p[3] === 'read' || p[3] === 'skim').length;
    swap(st, `${Q.length} searches, ${read} pages read`); say(`Done: ${Q.length} searches, ${read} pages read`);
    await c.wait(400); setOpen(false);
    const A = 'Stripe caps metered usage at 100 million events a month for each meter [1]. Metronome and Orb both take events in bulk with no monthly cap [2]. At your volume Stripe still fits, with room to grow.'.split(' ');
    for (let i = 1; i <= A.length; i++){ ans.innerHTML = A.slice(0, i).join(' ').replace(/\[(\d)\]/g, (m, k) => `<button class="wsx-cite" data-n="${k}" aria-label="Source ${k}: ${$('.t', pages[k].li).textContent}, ${pages[k].d}" data-tip="${$('.t', pages[k].li).textContent} · ${pages[k].d}">${k}</button>`); await c.wait(50); }

  });
  // a citation lights the page it came from (and the query that found it), and its site's mark
